# Matrix-3D (Skywork) on Kaggle's two T4s: the real room as a 360 panorama -> walk-through panorama video -> 3D.
# The panorama comes from our own Depth Anything 3 points of the 4K room video (55% unseen, filled by SDXL inpainting),
# so the generated world starts from the real room instead of an invented one.
import base64, os, subprocess, sys, time
T0 = time.time()
def sh(c):
    print(f'\n[{time.time()-T0:6.0f}s] $ {c[:200]}', flush=True)
    return subprocess.call(c, shell=True, executable='/bin/bash')
W = '/kaggle/temp/m3d'; O = '/kaggle/working'; CASE = f'{W}/repo/output/room'
os.makedirs(W, exist_ok=True)
open(f'{W}/pano_raw.jpg', 'wb').write(base64.b64decode(''))
P = f'--python {W}/env/bin/python'
sh(f'cd {W} && git clone -q --recursive --depth 1 https://github.com/SkyworkAI/Matrix-3D repo')
os.makedirs(CASE, exist_ok=True)
sh(f'unset UV_SYSTEM_PYTHON UV_PYTHON; cd {W} && uv venv -q -p 3.11 env && '
   f'uv pip install -q {P} torch==2.7.1 torchvision==0.22.1 --index-url https://download.pytorch.org/whl/cu128 > pip.log 2>&1; '
   f'for r in ninja setuptools wheel "diffusers==0.34.0" "transformers==4.56.0" accelerate "modelscope==1.28.2" xfuser peft easydict '
   f'imageio imageio-ffmpeg opencv-python-headless einops plyfile trimesh py360convert decord safetensors sentencepiece ftfy '
   f'"git+https://github.com/EasternJournalist/utils3d.git" scipy open3d natsort; do uv pip install -q {P} "$r" >> pip.log 2>&1 || echo "FAILED $r"; done; '
   f'uv pip install -q {P} -e repo/code/DiffSynth-Studio >> pip.log 2>&1 || echo FAILED diffsynth; '
   f'uv pip install -q {P} --no-build-isolation ./repo/submodules/nvdiffrast >> pip.log 2>&1 || echo FAILED nvdiffrast; tail -5 pip.log')
PY = f'{W}/env/bin/python'
# Fill the unseen half of the panorama (SDXL inpainting, fp16, about a minute on a T4).
open(f'{W}/fill.py', 'w').write('''
import numpy as np, torch, cv2
from PIL import Image
from diffusers import AutoPipelineForInpainting
raw = cv2.imread("%s/pano_raw.jpg")
hole = (raw.sum(2) < 12).astype(np.uint8) * 255
hole = cv2.dilate(cv2.morphologyEx(hole, cv2.MORPH_OPEN, np.ones((5, 5), np.uint8)), np.ones((9, 9), np.uint8))
base = cv2.inpaint(raw, hole, 5, cv2.INPAINT_TELEA)
p = AutoPipelineForInpainting.from_pretrained("diffusers/stable-diffusion-xl-1.0-inpainting-0.1", torch_dtype=torch.float16, variant="fp16").to("cuda")
img = Image.fromarray(cv2.cvtColor(cv2.resize(base, (1536, 768)), cv2.COLOR_BGR2RGB))
m = Image.fromarray(cv2.resize(hole, (1536, 768)))
out = p(prompt="360 degree equirectangular panorama of a real indoor room, white walls, ceiling lights, tiled floor, photorealistic",
        negative_prompt="people, text, blurry, distorted", image=img, mask_image=m, width=1536, height=768,
        strength=0.99, num_inference_steps=30, guidance_scale=7.0).images[0]
out = np.array(out.resize((2048, 1024)))[:, :, ::-1]
keep = cv2.resize(255 - hole, (2048, 1024)) > 127
real = cv2.resize(raw, (2048, 1024))
out[keep] = real[keep]     # every pixel we actually saw stays the real one
cv2.imwrite("%s/pano_img.jpg", out, [cv2.IMWRITE_JPEG_QUALITY, 95])
''' % (W, CASE))
sh(f'{PY} {W}/fill.py && cp {CASE}/pano_img.jpg {O}/')
open(f'{CASE}/prompt.txt', 'w').write('a real indoor room, white walls, ceiling lights, tiled floor, photorealistic interior, natural lighting')
# Only what the 5B path needs (the repo script also pulls the 14B and 80 GB-VRAM models: tens of GB we can't hold).
open(f'{W}/dl.py', 'w').write('''
from huggingface_hub import hf_hub_download, snapshot_download
import shutil, os
os.chdir("%s/repo")
hf_hub_download("Ruicheng/moge-vitl", "model.pt", local_dir="checkpoints/moge")
import glob
p = glob.glob("/kaggle/input/**/pano_video_gen_720p_5b.safetensors", recursive=True)[0]   # gated on HF: brought in as a private dataset
os.makedirs("checkpoints/Wan-AI/wan-lora", exist_ok=True); shutil.copy(p, "checkpoints/Wan-AI/wan-lora/")
snapshot_download("Wan-AI/Wan2.2-TI2V-5B", local_dir="checkpoints/Wan-AI/Wan2.2-TI2V-5B",
                  allow_patterns=["*.safetensors", "*.json", "*.pth", "google/*"])
print("checkpoints ok")
''' % W)
sh(f'{PY} {W}/dl.py 2>&1 | tail -3; du -sh {W}/repo/checkpoints/*')
code = sh(f'cd {W}/repo && {W}/env/bin/torchrun --nproc_per_node 2 code/panoramic_image_to_video.py --inout_dir={CASE} '
          f'--resolution=720 --use_5b_model --enable_vram_management 2>&1 | grep -vE "it/s|s/it" | tail -60')
sh(f'cp {CASE}/*.mp4 {CASE}/*.jpg {CASE}/*.json {O}/ 2>/dev/null; ls -la {CASE} {O}')
sys.exit(code)
